OM_uint32 spnego_gss_init_reselect(OM_uint32 *minor_status, spnego_gss_ctx_id_t sc, OM_uint32 acc_negState, gss_OID supportedMech, gss_buffer_t *responseToken, gss_buffer_t *mechListMIC, OM_uint32 *negState, send_token_flag *tokflag) {
    OM_uint32 major_status = GSS_S_FAILURE;

    if (!minor_status || !responseToken || !mechListMIC || !negState || !tokflag) {
        if (minor_status) {
            *minor_status = 0;
        }
        return GSS_S_BAD_ARGUMENT;
    }

    if (sc == NULL) {
        if (minor_status) {
            *minor_status = 0;
        }
        return GSS_S_BAD_CONTEXT;
    }

    if (supportedMech == GSS_C_NO_OID) {
        if (minor_status) {
            *minor_status = 0;
        }
        return GSS_S_BAD_MECH;
    }

    if (acc_negState != GSS_S_CONTINUE_NEEDED && acc_negState != GSS_S_COMPLETE) {
        if (minor_status) {
            *minor_status = 0;
        }
        return GSS_S_BAD_SIG;
    }

    gss_delete_sec_context(minor_status, &sc, NULL);

    if (gss_oid_equal(supportedMech, GSS_C_NULL_OID)) {
        if (minor_status) {
            *minor_status = 0;
        }
        return GSS_S_BAD_OID;
    }

    if (acc_negState == GSS_S_COMPLETE) {
        *negState = acc_negState;
        *tokflag = SEND_TOKEN_FLAG_INIT;
        major_status = GSS_S_COMPLETE;
    } else {
        *negState = acc_negState;
        *tokflag = SEND_TOKEN_FLAG_CONTINUE;
        major_status = GSS_S_CONTINUE_NEEDED;
    }

    return major_status;
}
